#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
typedef __uint128_t u128;
typedef long long ll;
static const ll MOD = 1000000007LL;

// simple big unsigned, base 2^32, little endian
struct Big {
    vector<uint32_t> d;
    Big(ull x=0){ while(x){ d.push_back((uint32_t)(x&0xffffffffu)); x>>=32; } }
    ull mod64(ull m) const {
        u128 rem=0;
        for(int i=(int)d.size()-1;i>=0;--i){ rem=((rem<<32)|d[i])%m; }
        return (ull)rem;
    }
    void div64(ull g){ // exact division
        u128 rem=0;
        for(int i=(int)d.size()-1;i>=0;--i){ u128 cur=(rem<<32)|d[i]; d[i]=(uint32_t)(cur/g); rem=cur%g; }
        while(!d.empty() && d.back()==0) d.pop_back();
    }
    void mul64(ull m){
        u128 carry=0;
        for(size_t i=0;i<d.size();++i){ u128 cur=(u128)d[i]*m+carry; d[i]=(uint32_t)(cur&0xffffffffu); carry=cur>>32; }
        while(carry){ d.push_back((uint32_t)(carry&0xffffffffu)); carry>>=32; }
    }
    ll modp(ll p) const {
        u128 rem=0;
        for(int i=(int)d.size()-1;i>=0;--i){ rem=((rem<<32)|d[i])%p; }
        return (ll)rem;
    }
};

static ull igcd(ull a, ull b){ while(b){ ull t=a%b; a=b; b=t;} return a; }

vector<ll> solve(const vector<ull>& a, int n, const vector<pair<int,int>>& qs){
    int Q=qs.size();
    vector<vector<pair<int,int>>> byr(n+1);
    for(int i=0;i<Q;i++) byr[qs[i].second].push_back({qs[i].first,i});
    vector<ll> ans(Q);
    vector<ll> dp(n+1,0);
    vector<ull> G(n+1,1);
    for(int r=1;r<=n;r++){
        ull ar=a[r]; ull cur=1;
        for(int l=r-1;l>=1;l--){
            ull c=igcd(ar,a[l]);
            if(cur%c!=0){ ull g=igcd(cur,c); cur=(cur/g)*c; }
            G[l]=cur;
        }
        for(int l=1;l<=r-1;l++){
            ull f=ar/G[l];
            if(f!=1) dp[l]=dp[l]*(ll)(f%(ull)MOD)%MOD;
        }
        dp[r]=(ll)(ar%(ull)MOD);
        for(auto&pr:byr[r]) ans[pr.second]=dp[pr.first];
    }
    return ans;
}

int main(){
    mt19937_64 rng(20240607);
    int iters=200000;
    ull MASK=((ull)1<<60)-1;
    for(int it=0; it<iters; ++it){
        int n=1+rng()%6;
        vector<ull> a(n+1);
        for(int i=1;i<=n;i++){
            int mode=rng()%3;
            if(mode==0){ ull v=rng()&MASK; a[i]= v? v:1; }
            else if(mode==1){ // small prime powers times random
                ull v=1; v *= (1ULL<<(rng()%60)); if(v==0) v=1; a[i]=v;
            }
            else { ull v=(rng()&MASK); if(v==0)v=1; a[i]=v; }
        }
        vector<pair<int,int>> qs;
        vector<ll> exp;
        for(int l=1;l<=n;l++)for(int r=l;r<=n;r++){
            qs.push_back({l,r});
            Big L(1);
            for(int i=l;i<=r;i++){
                ull r2=L.mod64(a[i]);
                ull g=igcd(r2,a[i]);
                L.div64(g); L.mul64(a[i]);
            }
            exp.push_back(L.modp(MOD));
        }
        vector<ll> got=solve(a,n,qs);
        for(size_t i=0;i<qs.size();i++){
            if(got[i]!=exp[i]){
                printf("MISMATCH it=%d n=%d a=",it,n);
                for(int i=1;i<=n;i++) printf("%llu ",a[i]);
                printf("| q=(%d,%d) exp=%lld got=%lld\n",qs[i].first,qs[i].second,exp[i],got[i]);
                fflush(stdout);
                return 0;
            }
        }
    }
    printf("ALL OK\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ull;
typedef long long ll;
static const ll MOD = 1000000007LL;
static inline ull igcd(ull a, ull b){ while(b){ ull t=a%b; a=b; b=t;} return a; }
static inline ull bingcd(ull a, ull b){
    if(!a) return b; if(!b) return a;
    int sa=__builtin_ctzll(a), sb=__builtin_ctzll(b);
    a>>=sa; b>>=sb;
    int s=min(sa,sb);
    while(a!=b){ if(a>b){ a-=b; a>>=__builtin_ctzll(a);} else { b-=a; b>>=__builtin_ctzll(b);} }
    return a<<s;
}
static ull a[305],G[305];
static ll dp[305];
int main(){
    // Fibonacci up to 2^60
    vector<ull> fib={1,1};
    while(true){ ull nxt=fib[fib.size()-1]+fib[fib.size()-2]; if(nxt>(1ULL<<60)) break; fib.push_back(nxt); }
    ull F1=fib[fib.size()-1], F2=fib[fib.size()-2];
    printf("F2=%llu F1=%llu\n",F2,F1);
    int T=300,n=300;
    for(int which=0; which<2; ++which){
        auto t0=chrono::high_resolution_clock::now();
        for(int tc=0;tc<T;tc++){
            for(int i=1;i<=n;i++) a[i]= (i&1)?F2:F1;
            for(int r=1;r<=n;r++){
                ull ar=a[r],cur=1;
                for(int l=r-1;l>=1;l--){
                    ull c= which? bingcd(ar,a[l]) : igcd(ar,a[l]);
                    if(cur%c!=0){ ull g= which? bingcd(cur,c): igcd(cur,c); cur=(cur/g)*c; }
                    G[l]=cur;
                }
                for(int l=1;l<=r-1;l++){ ull f=ar/G[l]; if(f!=1) dp[l]=dp[l]*(ll)(f%(ull)MOD)%MOD; }
                dp[r]=(ll)(ar%(ull)MOD);
            }
        }
        auto t1=chrono::high_resolution_clock::now();
        printf("%s: %.1f ms\n", which? "bingcd":"euclid", chrono::duration<double,milli>(t1-t0).count());
    }
    return 0;
}

