            if(mode==0){ v=rng()&MASK; if(!v)v=1; }
            else if(mode==1){ v=rng()%1000000+1; }
            else if(mode==2){ v=1ULL<<(rng()%60); if(!v)v=1; }
            else { v=(rng()%1000000+1)*1000000+ (rng()%1000000+1); }
            a[i]=v;
        }
        vector<pair<int,int>> qs; vector<ll> exp;
        for(int l=1;l<=n;l++)for(int r=l;r<=n;r++){
            qs.push_back({l,r}); Big L(1);
            for(int i=l;i<=r;i++){ ull r2=L.mod64(a[i]); ull g=igcd(r2,a[i]); L.div64(g); L.mul64(a[i]); }
            exp.push_back(L.modp(MOD));
        }
        vector<ll> got=solve_offline(a,n,qs);
        for(size_t i=0;i<qs.size();i++) if(got[i]!=exp[i]){
            printf("MISMATCH it=%d n=%d a=",it,n); for(int i=1;i<=n;i++) printf("%llu ",a[i]);
            printf("| q=(%d,%d) exp=%lld got=%lld\n",qs[i].first,qs[i].second,exp[i],got[i]); fflush(stdout); return 0;
        }
    }
    printf("ALL OK\n"); return 0;
