static ull genSmooth(mt19937_64&rng, const vector<ull>&P){
    ull v=1;
    for(size_t i=0;i<P.size();i++){ int e=rng()%4; for(int k=0;k<e;k++){ if(v>(~0ULL)/P[i])break; v*=P[i]; } }
    return v?v:1;
